# Each audited template has eight distinct named contexts, not a claim of 896 independent rules.
contexts=[dict(N=n,T=t,P=p) for n,t,p in [('Alex','ticket','tickets'),('Jo','map','maps'),('Sam','letter','letters'),('Kim','coat','coats'),('Lee','key','keys'),('Robin','bag','bags'),('Taylor','book','books'),('Morgan','lamp','lamps')]]
f={k:[] for k in ['easy','medium','hard','master']}
def q(l,p,a,*w):
 assert len(w)==3 and len(set([a,*w]))==4,(p,a,w)
 f[l].append((p,a,w))
