rows=[]
for l,templates in f.items():
 assert len(templates)==28,(l,len(templates))
 for c in contexts:
  for idx,(p,a,w) in enumerate(templates):
   rows.append(dict(question=p.format(**c),correct=a.format(**c),wrong=[x.format(**c) for x in w],level=l,family=f'{l}-{idx+1:02d}'))
assert len(rows)==896
assert len(set(r['question'] for r in rows))==896
out=pathlib.Path('/home/sandbox/ct-prod/src/lib/trivia-grammar.ts')
out.write_text('// Embedded offline Grammar bank: 896 questions,224 per level.\n// 112 reviewed question templates, eight named contexts each. No runtime generation.\n// Standard written English; labelled register where it affects the answer.\nimport type { LocalQuestion } from \'./trivia-local\';\nexport const GRAMMAR_CATEGORY_ID = -14;\nexport const GRAMMAR_CATEGORIES = [{ id: GRAMMAR_CATEGORY_ID, name: \'Grammar\' }];\nexport const GRAMMAR_QUESTIONS: Record<number, LocalQuestion[]> = {\n  [GRAMMAR_CATEGORY_ID]: '+json.dumps(rows,ensure_ascii=False,indent=2)+'\n};\n')
print(collections.Counter(r['level'] for r in rows))
